function highlightColumnAtPoint(x,y){var columns=document.querySelectorAll('.mw-day-column');columns.forEach(function(col){var rect=col.getBoundingClientRect();var inside=(x>=rect.left&&x<=rect.right&&y>=rect.top&&y<=rect.bottom);if(inside){col.classList.add('drag-over')}else{col.classList.remove('drag-over')}})}
function showCapacityWarning(card,newDate,newRouteOrder,message){if(!feedbackEl||!feedbackMsg)return;feedbackMsg.textContent=message||'Crew day is over capacity — continue?';feedbackEl.className='mw-drag-feedback warning';feedbackEl.style.display='block';var btn=document.createElement('button');btn.type='button';btn.textContent='Continue anyway';btn.className='mw-cap-confirm-btn';btn.style.cssText='margin-left:10px;padding:2px 10px;font-size:11px;cursor:pointer;background:#e85d04;color:#fff;border:none;border-radius:4px;';feedbackEl.appendChild(btn);btn.addEventListener('click',function(){btn.remove();var stopId=parseInt(card.dataset.stopId,10);card.style.opacity='0.5';showFeedback('Moving stop...','loading');fetch('/crm/api/reschedule-stop.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({stop_id:stopId,new_date:newDate,new_route_order:newRouteOrder,force:1})}).then(function(r){return r.json()}).then(function(data){card.style.opacity='1';if(data&&data.success){showFeedback('Stop moved (over capacity)','success');setTimeout(function(){location.reload()},1500)}else{showFeedback(data.error||'Move failed','error')}}).catch(function(){card.style.opacity='1';showFeedback('Connection error','error')})})}
function showFeedback(message,type){if(!feedbackEl||!feedbackMsg)return;type=type||'info';feedbackMsg.textContent=message;feedbackEl.className='mw-drag-feedback';if(type==='error'){feedbackEl.classList.add('error')}else if(type==='success'){feedbackEl.classList.add('success')}else if(type==='warning'){feedbackEl.classList.add('warning')}
feedbackEl.style.display='block';var timeout;switch(type){case 'error':timeout=10000;break;case 'loading':timeout=10000;break;case 'success':timeout=3000;break;case 'warning':timeout=4000;break;default:timeout=3000}
setTimeout(function(){feedbackEl.style.display='none'},timeout)}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initDragAndDrop)}else{initDragAndDrop()}
